// Generated by build-game-assets.cjs for direct HTML play.
(()=>{
// Optional Three.js helper. Load player_ship.glb with GLTFLoader, then call this.
// Does not change the game; this module packages the asset's switching contract.
function assemblePlayerShip(gltf) {
  const ship=gltf.scene, library=gltf.scenes[1], parts=new Map();
  for(const root of gltf.scenes)root.traverse(o=>{if(o.userData.component)parts.set(o.userData.component,o);});
  const pitch=ship.getObjectByName('mining_dish_pitch');
  ship.updateMatrixWorld(true);library.updateMatrixWorld(true);
  // Attach all alternatives once, preserving the authored local ship pose.
  for(const node of [...library.children])ship.attach(node);
  for(let i=1;i<=3;i++)pitch.attach(parts.get('laser_barrel_'+i));
  const choose=(prefix,value)=>{for(const [name,node] of parts)if(name.startsWith(prefix+'_'))node.visible=name===prefix+'_'+value;};
  const configure=({wings='delta',laser=1,cargo=1,engine=1,scanner=1}={})=>{
    if(!['delta','swept','forward','twin'].includes(wings)||![laser,cargo,engine,scanner].every(v=>[1,2,3].includes(v)))throw new RangeError('Unknown player ship configuration');
    choose('wings',wings);choose('laser_barrel',laser);choose('cargo_pod',cargo);choose('engine_nacelle',engine);choose('scanner_dish',scanner);
    const wing=parts.get('wings_'+wings);ship.getObjectByName('nav_l').position.fromArray(wing.userData.nav_l);ship.getObjectByName('nav_r').position.fromArray(wing.userData.nav_r);
    // Focus local to the pitch pivot, matching the selected barrel's front face.
    ship.getObjectByName('focus').position.set(0,0,1.69+laser*.48);
  };
  configure();
  return {ship,parts,configure,yaw:ship.getObjectByName('mining_dish_yaw'),pitch};
}

window.assembleBeltRunnerPlayerShip=assemblePlayerShip;
})();
